class Engine {
  constructor(power) {
    this.power = power;
  }

  getThrustPower() {
    return this.power;
  }
}

class Weapon {
  constructor(power) {
    this.power = power;
  }

  getAttackPower() {
    return this.power;
  }
}

class Shield {
  constructor(power) {
    this.power = power;
  }

  getDefensePower() {
    return this.power;
  }
}

class Spaceship {
  constructor(name) {
    this.name = name;
    this.engine = null;
    this.weapon = null;
    this.shield = null;
  }

  setEngine(engine) {
    const power = engine?.getThrustPower();
    if (power > 0) {
      this.engine = engine;
    } else {
      console.error("Invalid engine: Thrust power must be positive.");
    }
  }

  setWeapon(weapon) {
    const power = weapon?.getAttackPower();
    if (power > 0) {
      this.weapon = weapon;
    } else {
      console.error("Invalid weapon: Attack power must be positive.");
    }
  }

  setShield(shield) {
    const power = shield?.getDefensePower();
    if (power > 0) {
      this.shield = shield;
    } else {
      console.error("Invalid shield: Defense power must be positive.");
    }
  }

  getTotalCombatPower() {
    const enginePower = this.engine?.getThrustPower() || 0;
    const weaponPower = this.weapon?.getAttackPower() || 0;
    return enginePower + weaponPower;
  }

  getTotalDefense() {
    return this.shield?.getDefensePower() || 0;
  }
}

